import numpy as np
import matplotlib.pyplot as plt
import control as ctrl
plt.rcParams.update({'font.family':'DejaVu Sans','axes.unicode_minus':False})
w=np.r_[0.,np.logspace(-3,3,1201)]
def matrix(b=2.,c=.125,omega=0.):return np.array([[0.,b],[c,0.]],dtype=complex)/(1+1j*omega)
def top(M):return float(np.linalg.svd(M,compute_uv=False)[0])
def diag_mu(b,c,omega=0.):return np.sqrt(abs(b*c))/np.hypot(1.,omega)
def diag_witness(b,c,omega=0.):
    if b*c==0:return None
    q=(1+1j*omega)/np.sqrt(abs(b*c));return np.diag([q,np.sign(b*c)*q])
def full_witness(M):
    U,s,Vh=np.linalg.svd(M)
    return None if s[0]==0 else np.outer(Vh.conj().T[:,0],U[:,0].conj())/s[0]
def physical_poles(b,c,Delta):return np.linalg.eigvals(-np.eye(2)+Delta@np.array([[0.,b],[c,0.]]))

